{
  "application": "poster-generation",
  "case_id": "case-econ-global-economic-prospects-2025",
  "language": "en",
  "source_brief": "/app/benchmark/source_brief.md",
  "poster": {
    "aspect_ratio": "A1-portrait",
    "audience": "data-report",
    "tone": "data-forward, professional",
    "venue": null
  },
  "brief": {
    "title": "Global Economic Prospects: Resilience Amid Uncertainty",
    "one_liner": "The global economy has recovered strongly from the 2020 recession, but vulnerable economies lag behind as trade tensions and policy uncertainty cloud the outlook.",
    "goal": "Viewers should understand the current state of global economic resilience, the risks posed by trade tensions and policy uncertainty, the divergence between advanced and vulnerable economies, and the World Bank's strategic priorities for sustainable and inclusive growth."
  },
  "sections": [
    {
      "id": "recovery-overview",
      "title": "A Historic Recovery — But Uneven",
      "objective": "Highlight that the post-2020 recovery is the strongest in six decades, while emphasizing the gap for vulnerable emerging market and developing economies."
    },
    {
      "id": "risks-outlook",
      "title": "Risks to the Outlook",
      "objective": "Communicate the key downside risks: escalating trade tensions, tariff effects, inventory drawdowns, and financial market sentiment deterioration."
    },
    {
      "id": "policy-actions",
      "title": "Policy Actions for Sustained Growth",
      "objective": "Summarize the global and domestic reform agenda — improving trade environments, easing financing, mitigating climate risks, diversifying trade, and removing structural bottlenecks."
    },
    {
      "id": "strategic-priorities",
      "title": "World Bank 2030 Strategic Priorities",
      "objective": "Present the Bank's flagship targets: health services, electricity access, agricultural value chains, women's capital access, and water security."
    },
    {
      "id": "research-themes",
      "title": "Key Research Themes in Recent Issues",
      "objective": "Provide a snapshot of the analytical depth behind the report, covering fiscal policy, trade costs, commodity cycles, and pandemic economics."
    }
  ],
  "metrics": [
    {
      "label": "Youth entering working age (next decade)",
      "value": "1.2 billion"
    },
    {
      "label": "Health services target",
      "value": "1.5 billion people"
    },
    {
      "label": "Mission 300 — Electricity in Sub-Saharan Africa",
      "value": "300 million people"
    },
    {
      "label": "AgriConnect — Farmers up the value chain",
      "value": "300 million farmers"
    },
    {
      "label": "Women's capital access target",
      "value": "80 million women & women-led businesses"
    },
    {
      "label": "Water Forward commitment",
      "value": "1 billion+ people; 400 million WBG commitment"
    },
    {
      "label": "Recovery benchmark",
      "value": "Strongest in 6 decades"
    }
  ]
}

