<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Global Economic Prospects - Infographic</title>
  <style>
    * { margin: 0; padding: 0; box-sizing: border-box; }
    html, body {
      width: 100%;
      height: 100%;
      background: #f0f4f8;
      display: flex;
      align-items: center;
      justify-content: center;
    }
    #container {
      width: 794px;
      height: 1123px;
      background: white;
    }
    #export-btn {
      position: fixed;
      top: 16px;
      right: 16px;
      padding: 8px 16px;
      background: #1e40af;
      color: white;
      border: none;
      border-radius: 6px;
      cursor: pointer;
      font-size: 14px;
      z-index: 9999;
    }
    #export-btn:hover { background: #1e3a8a; }
  </style>
</head>
<body>
  <button id="export-btn" onclick="exportSVG()">Export SVG</button>
  <div id="container"></div>
  <script src="/app/vendor/infographic.min.js"></script>
  <script>
    const syntax = `infographic list-waterfall-badge-card
data
  title Global Economic Prospects: Resilience Amid Uncertainty
  desc Strongest post-recession recovery in 6 decades — but vulnerable economies lag as trade tensions and policy uncertainty cloud the outlook
  lists
    - label Strongest Recovery in 6 Decades
      value 6
      desc Post-2020 rebound outpaces all recoveries since the 1960s — yet growth is projected to edge down as tariff effects and inventory corrections weigh on demand
      icon trending up
    - label 1.2 Billion Youth
      value 1.2B
      desc Young people reaching working age in the next decade — placing job creation at the center of the World Bank Group mission
      icon people group
    - label Trade Tensions — Top Risk
      value 1
      desc Escalating tariffs and retaliatory measures threaten supply chains, dampen investment, and tighten financing conditions for emerging markets
      icon warning triangle
    - label Financial Volatility Risk
      value 2
      desc Deteriorating market sentiment could sharply tighten financing conditions — especially for vulnerable EMDEs already lagging advanced economies
      icon chart line down
    - label Health Services 2030
      value 1.5B
      desc World Bank target: deliver quality, affordable health services to 1.5 billion people by 2030
      icon heart medical
    - label Mission 300 — Electricity
      value 300M
      desc Provide 300 million people in Sub-Saharan Africa with electricity access — catalyzing productivity and inclusion
      icon lightning bolt
    - label AgriConnect Farmers
      value 300M
      desc Help 300 million farmers move up the agricultural value chain, boosting rural incomes and food security
      icon leaf nature
    - label Women's Capital Access
      value 80M
      desc Extend access to capital for 80 million women and women-led businesses — closing the gender finance gap
      icon person female
    - label Water Forward
      value 1B+
      desc Improve water security for over 1 billion people; World Bank Group commits 400 million to lead this initiative
      icon water drop
theme
  palette #1e3a8a #0e7490 #0369a1 #b45309 #1d4ed8`;

    const infographic = new AntVInfographic.Infographic({
      container: '#container',
      width: '100%',
      height: '100%',
    });

    infographic.render(syntax);

    document.fonts?.ready.then(() => {
      infographic.render(syntax);
    }).catch((error) => console.error('Error waiting for fonts to load:', error));

    async function exportSVG() {
      try {
        const svgDataUrl = await infographic.toDataURL({ type: 'svg' });
        const link = document.createElement('a');
        link.href = svgDataUrl;
        link.download = 'global-economic-prospects.svg';
        link.click();
      } catch (e) {
        console.error('Export failed:', e);
        alert('Export failed: ' + e.message);
      }
    }
  </script>
</body>
</html>
