<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Global Economic Prospects - Poster</title>
  <style>
    @import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800;900&display=swap');

    * { margin: 0; padding: 0; box-sizing: border-box; }

    body {
      font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
      background: #e8edf2;
      display: flex;
      justify-content: center;
      align-items: flex-start;
      padding: 32px;
      min-height: 100vh;
    }

    .poster {
      width: 1587px;
      min-height: 2245px;
      background: #f8fafc;
      position: relative;
      overflow: hidden;
    }

    /* ── HEADER ── */
    .header {
      background: linear-gradient(135deg, #0f2d5e 0%, #1a4a8a 60%, #0e6b9e 100%);
      padding: 60px 80px 50px;
      position: relative;
      overflow: hidden;
    }
    .header::before {
      content: '';
      position: absolute;
      top: -80px; right: -80px;
      width: 400px; height: 400px;
      border-radius: 50%;
      background: rgba(255,255,255,0.04);
    }
    .header::after {
      content: '';
      position: absolute;
      bottom: -60px; left: 200px;
      width: 300px; height: 300px;
      border-radius: 50%;
      background: rgba(255,255,255,0.03);
    }
    .header-tag {
      display: inline-block;
      background: rgba(255,255,255,0.15);
      color: #93c5fd;
      font-size: 13px;
      font-weight: 600;
      letter-spacing: 1.5px;
      text-transform: uppercase;
      padding: 6px 14px;
      border-radius: 4px;
      margin-bottom: 20px;
    }
    .header h1 {
      font-size: 52px;
      font-weight: 800;
      color: #ffffff;
      line-height: 1.15;
      max-width: 900px;
      margin-bottom: 16px;
      letter-spacing: -0.5px;
    }
    .header h1 em {
      font-style: normal;
      color: #f59e0b;
    }
    .header-sub {
      font-size: 18px;
      color: #bfdbfe;
      line-height: 1.6;
      max-width: 860px;
      font-weight: 400;
    }
    .header-badge {
      position: absolute;
      top: 50px; right: 80px;
      background: rgba(245,158,11,0.2);
      border: 2px solid rgba(245,158,11,0.5);
      border-radius: 12px;
      padding: 18px 26px;
      text-align: center;
    }
    .header-badge .hb-num {
      font-size: 42px;
      font-weight: 900;
      color: #f59e0b;
      line-height: 1;
    }
    .header-badge .hb-label {
      font-size: 13px;
      color: #fde68a;
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 0.8px;
      margin-top: 6px;
    }

    /* ── BODY ── */
    .body {
      padding: 48px 80px;
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 40px;
    }

    /* ── SECTION CARD ── */
    .section {
      background: white;
      border-radius: 16px;
      padding: 36px 36px 32px;
      border: 1px solid #e2e8f0;
      box-shadow: 0 2px 12px rgba(0,0,0,0.05);
      position: relative;
    }
    .section.full-width {
      grid-column: 1 / -1;
    }
    .section-tag {
      display: inline-block;
      font-size: 11px;
      font-weight: 700;
      letter-spacing: 1.2px;
      text-transform: uppercase;
      padding: 4px 10px;
      border-radius: 4px;
      margin-bottom: 10px;
    }
    .section h2 {
      font-size: 22px;
      font-weight: 700;
      color: #0f2d5e;
      margin-bottom: 20px;
      padding-bottom: 14px;
      border-bottom: 2px solid #e2e8f0;
      line-height: 1.3;
    }
    .section h2 .accent { color: #f59e0b; }

    /* ── RECOVERY SECTION ── */
    .recovery-highlight {
      display: flex;
      align-items: center;
      gap: 24px;
      background: linear-gradient(135deg, #eff6ff 0%, #dbeafe 100%);
      border-radius: 12px;
      padding: 24px;
      margin-bottom: 20px;
      border-left: 5px solid #1d4ed8;
    }
    .rh-stat {
      text-align: center;
      min-width: 100px;
    }
    .rh-stat .big { font-size: 48px; font-weight: 900; color: #1d4ed8; line-height: 1; }
    .rh-stat .unit { font-size: 14px; font-weight: 600; color: #3b82f6; text-transform: uppercase; letter-spacing: 0.5px; margin-top: 2px; }
    .rh-text { font-size: 15px; color: #334155; line-height: 1.65; }
    .rh-text strong { color: #0f2d5e; }

    .divergence-row {
      display: flex;
      gap: 16px;
    }
    .div-card {
      flex: 1;
      border-radius: 10px;
      padding: 16px 18px;
    }
    .div-card.advanced { background: #f0fdf4; border-left: 4px solid #16a34a; }
    .div-card.vulnerable { background: #fff7ed; border-left: 4px solid #ea580c; }
    .div-card .dc-label { font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: 1px; margin-bottom: 6px; }
    .div-card.advanced .dc-label { color: #16a34a; }
    .div-card.vulnerable .dc-label { color: #ea580c; }
    .div-card .dc-body { font-size: 13.5px; color: #475569; line-height: 1.55; }

    /* ── RISKS SECTION ── */
    .risk-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 14px; }
    .risk-item {
      border-radius: 10px;
      padding: 18px;
      position: relative;
    }
    .risk-item.primary { background: #fef2f2; border: 1.5px solid #fca5a5; }
    .risk-item.secondary { background: #fff7ed; border: 1.5px solid #fdba74; }
    .risk-item .ri-icon {
      font-size: 22px;
      margin-bottom: 8px;
      display: block;
    }
    .risk-item .ri-title { font-size: 14px; font-weight: 700; color: #0f2d5e; margin-bottom: 5px; }
    .risk-item.primary .ri-badge {
      display: inline-block;
      background: #dc2626;
      color: white;
      font-size: 10px;
      font-weight: 700;
      padding: 2px 7px;
      border-radius: 3px;
      text-transform: uppercase;
      letter-spacing: 0.5px;
      margin-bottom: 8px;
    }
    .risk-item .ri-body { font-size: 13px; color: #64748b; line-height: 1.55; }

    /* ── POLICY SECTION ── */
    .policy-table { width: 100%; border-collapse: collapse; }
    .policy-table th {
      background: #0f2d5e;
      color: white;
      font-size: 12px;
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 0.8px;
      padding: 11px 16px;
      text-align: left;
    }
    .policy-table th:first-child { border-radius: 8px 0 0 0; }
    .policy-table th:last-child { border-radius: 0 8px 0 0; }
    .policy-table td {
      padding: 11px 16px;
      font-size: 13.5px;
      color: #334155;
      border-bottom: 1px solid #f1f5f9;
      vertical-align: top;
      line-height: 1.5;
    }
    .policy-table tr:nth-child(even) td { background: #f8fafc; }
    .policy-table td:first-child { font-weight: 600; color: #0f2d5e; }
    .area-badge {
      display: inline-block;
      padding: 3px 9px;
      border-radius: 4px;
      font-size: 12px;
      font-weight: 600;
      background: #eff6ff;
      color: #1d4ed8;
    }

    /* ── 2030 TARGETS ── */
    .targets-intro {
      display: flex;
      align-items: center;
      gap: 20px;
      background: linear-gradient(135deg, #fefce8 0%, #fef3c7 100%);
      border-radius: 12px;
      padding: 20px 24px;
      margin-bottom: 24px;
      border-left: 5px solid #d97706;
    }
    .ti-stat .big { font-size: 52px; font-weight: 900; color: #b45309; line-height: 1; }
    .ti-stat .unit { font-size: 12px; font-weight: 700; color: #d97706; text-transform: uppercase; letter-spacing: 0.5px; }
    .ti-text { font-size: 15px; color: #78350f; line-height: 1.6; }
    .ti-text strong { font-weight: 700; }

    .targets-grid { display: grid; grid-template-columns: repeat(5, 1fr); gap: 14px; }
    .target-card {
      background: white;
      border: 1.5px solid #e2e8f0;
      border-radius: 12px;
      padding: 18px 14px;
      text-align: center;
      box-shadow: 0 2px 8px rgba(0,0,0,0.04);
      position: relative;
      overflow: hidden;
    }
    .target-card::before {
      content: '';
      position: absolute;
      top: 0; left: 0; right: 0;
      height: 4px;
    }
    .target-card:nth-child(1)::before { background: #1d4ed8; }
    .target-card:nth-child(2)::before { background: #0e7490; }
    .target-card:nth-child(3)::before { background: #16a34a; }
    .target-card:nth-child(4)::before { background: #d97706; }
    .target-card:nth-child(5)::before { background: #7c3aed; }
    .tc-icon { font-size: 28px; margin-bottom: 8px; display: block; }
    .tc-value { font-size: 22px; font-weight: 800; line-height: 1; margin-bottom: 5px; }
    .target-card:nth-child(1) .tc-value { color: #1d4ed8; }
    .target-card:nth-child(2) .tc-value { color: #0e7490; }
    .target-card:nth-child(3) .tc-value { color: #16a34a; }
    .target-card:nth-child(4) .tc-value { color: #d97706; }
    .target-card:nth-child(5) .tc-value { color: #7c3aed; }
    .tc-initiative { font-size: 12px; font-weight: 700; color: #0f2d5e; margin-bottom: 5px; line-height: 1.3; }
