ER -->", "+  <div class="footer">", "+    <div class="footer-left">", "+      <strong>World Bank Group — Global Economic Prospects</strong>", "+      Data and analysis drawn from the Global Economic Prospects report series &nbsp;·&nbsp; worldbank.org/gep", "+    </div>", "+    <div class="footer-right">", "+      <div class="footer-tag">2025 Edition</div>", "+      <div>Policy Intelligence &nbsp;|&nbsp; Emerging Markets &nbsp;|&nbsp; Development Finance</div>", "+    </div>", "+  </div>", "+", "+</div><!-- /poster -->", " </body>", " </html>"]}], "originalFile": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8" />
