  <title>Global Economic Prospects - Infographic</title>
  <style>
    * { margin: 0; padding: 0; box-sizing: border-box; }
    html, body {
      width: 100%;
      height: 100%;
      background: #f0f4f8;
      display: flex;
      align-items: center;
      justify-content: center;
    }
    #container {
      width: 1587px;
      height: 2245px;
      background: white;
    }
    #export-btn {
      position: fixed;
      top: 16px;
      right: 16px;
      padding: 8px 16px;
      background: #1e40af;
      color: white;
      border: none;
      border-radius: 6px;
